import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
const packageRoot = resolve("extensions/sdk-ts/node_modules/@earendil-works/pi-coding-agent");
if (JSON.parse(readFileSync(resolve(packageRoot, "package.json"), "utf8")).version !== "1.0.0") throw new Error("unexpected Pi version");
const { createExtensionRuntime, loadExtensions } = await import(pathToFileURL(resolve(packageRoot, "dist/core/extensions/loader.js")));
const fixtureRoot = resolve("test/parity/scenarios/extensions-runtime/testdata/factory-failure");
const failing = resolve(fixtureRoot, "failing.mjs");
const survivor = resolve(fixtureRoot, "survivor.mjs");
const runtime = createExtensionRuntime();
const removed = [];
const unregister = runtime.unregisterProvider;
runtime.unregisterProvider = name => { removed.push(name); unregister(name); };
const working = resolve(fixtureRoot, "working.mjs");
const loaded = await loadExtensions([working, failing, survivor], process.cwd(), undefined, runtime);
if (loaded.errors.length !== 1 || loaded.errors[0].error !== "Failed to load extension: factory failed" || loaded.extensions.length !== 2) throw new Error(JSON.stringify(loaded.errors));
console.log(loaded.errors[0].error);
console.log(loaded.extensions[1].commands.get("factory-failure-report").description);
console.log(JSON.stringify({ failedFlagPresent: runtime.flagValues.has("failed-flag"), timerFlagPresent: runtime.flagValues.has("timer-flag"), providers: runtime.pendingProviderRegistrations.map(({ name, config }) => ({ name, config })), removed }));
